        let _ = fs::remove_dir_all("/app/packbay/stage");
        let _ = fs::remove_dir_all("/app/packbay/latest");
        fs::create_dir_all("/app/packbay/stage").ok();
        fs::create_dir_all("/app/packbay/latest").ok();
        return Ok((Vec::new(), 0));
