use std::fs;

fn emit(probe: &str, matched: i32, taken: i32) -> Result<(), i32> {
    let template = fs::read_to_string("/app/millrib/sheet.tpl").map_err(|_| 1)?;
    let output = template
        .replace("__P__", probe)
        .replace("__M__", &matched.to_string())
        .replace("__T__", &taken.to_string());
    fs::create_dir_all("/app/bloturn").map_err(|_| 1)?;
    fs::write("/app/bloturn/check.json", output).map_err(|_| 1)
}

pub fn gait(taken: i32, files: &[(i32, String)]) -> i32 {
    let _ = fs::remove_file("/app/bloturn/GUARD");
    let mut matched = 0;
    for (_, path) in files {
        if !path.starts_with("/app/daywell/") {
            return 1;
        }
        let text = match fs::read_to_string(path) {
            Ok(text) => text,
            Err(_) => return 1,
        };
        matched += text.lines().filter(|line| !line.trim().is_empty()).count() as i32;
    }
    if emit("live", matched, taken).is_err() || matched != taken {
        return 1;
    }
    if fs::write("/app/bloturn/GUARD", "ok").is_err() {
        return 1;
    }
    0
}
